// showcase/theme.css is GENERATED from the pinned @ocr/ui package: the base
// token sheet (design-system/tokens.css) plus the OW brand block, re-scoped from
// [data-brand="ow"] to :root so a standalone page carries it with no wrapper.
// Never edit theme.css by hand. Regenerate with:
//   UPDATE_THEME=1 npx vitest run --config showcase/vitest.config.mjs showcase/tests/contract.test.mjs
// The contract test fails whenever theme.css drifts from the pinned package.

export const THEME_HEADER =
  '/* GENERATED by showcase/lib/theme.mjs from @ocr/ui (the hub commit in .ocr-hub-ref).\n' +
  ' * Do not edit. Colours change only in packages/tokens, per the hub CHANGING-COLORS.md. */';

/**
 * @param {string} tokensCss  @ocr/ui design-system/tokens.css
 * @param {string} owBlock    brandBlock('ow') from @ocr/ui/tokens
 */
export function themeCss(tokensCss, owBlock) {
  // Same specificity as the base sheet's selectors, and later in the cascade, so
  // the brand wins in each of: default dark, OS light, forced light, forced dark.
  const scoped = owBlock
    .replaceAll('[data-theme="light"][data-brand="ow"]', ':root[data-theme="light"]')
    .replaceAll('[data-theme="dark"][data-brand="ow"]', ':root[data-theme="dark"]')
    .replace(/^ {2}\[data-brand="ow"\] \{/gm, '  :root:not([data-theme="dark"]) {')
    .replace(/^\[data-brand="ow"\] \{/gm, ':root {');
  if (scoped.includes('data-brand')) throw new Error('theme: an OW brand selector was not re-scoped');
  return `${THEME_HEADER}\n\n${tokensCss.trim()}\n\n/* OW brand (ourWKRP), re-scoped to :root */\n${scoped.trim()}\n`;
}
